package com.landportal.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="notifications") public class Notification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) User user; String message,notificationType; boolean readStatus=false; LocalDateTime createdAt; public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getNotificationType(){return notificationType;} public void setNotificationType(String v){notificationType=v;} public boolean isReadStatus(){return readStatus;} public void setReadStatus(boolean v){readStatus=v;} public LocalDateTime getCreatedAt(){return createdAt;} @PrePersist void init(){createdAt=LocalDateTime.now();} }
